"""Bounded independent identity/association check for the one maker-yellow cue."""
from common import *
from photo2.r336.revise import foreground,corridor
from photo2.r336.evidence import can_admit_identity
from glass_regions import REGIONS

def main():
 g,obs,co,rgb,auth,extra=load();candidate=next(r for r in read(ROOT/'photo2/r342/candidate-checks.json')['records'] if r['id']==C62);p=np.array(extra[C62]['xy']);cell=np.array(candidate['cell']);H=np.array(g['H']);local=sorted([o for o in co if np.linalg.norm(np.array(obs[o]['xy'])-p)<70],key=lambda o:np.linalg.norm(np.array(obs[o]['xy'])-p));aa=np.array([co[o] for o in local]);aa-=np.rint(((aa-cell)@H)/(H@H)).astype(int)[:,None]*H;X=np.c_[aa-cell,np.ones(len(aa))];B=np.linalg.lstsq(X,[obs[o]['xy'] for o in local],rcond=None)[0];grid=[cell+[a,b] for a in range(-3,4) for b in range(-3,4)];pred=[np.r_[q-cell,1]@B for q in grid];order=np.argsort([np.linalg.norm(q-p) for q in pred]);error=float(np.linalg.norm(pred[order[0]]-p));margin=float(np.linalg.norm(pred[order[1]]-p)-error);assert grid[order[0]].tolist()==cell.tolist();assert error<4 and margin>15
 colored=[o for o in local if obs[o]['color']!='black'];ab=np.array([co[o] for o in colored]);ab-=np.rint(((ab-cell)@H)/(H@H)).astype(int)[:,None]*H;bc=np.linalg.lstsq(np.c_[ab-cell,np.ones(len(ab))],[obs[o]['xy'] for o in colored],rcond=None)[0];prediction_spread=float(np.linalg.norm(bc[2]-B[2]));assert prediction_spread<3
 # Native independent body witness: a separately visible amber oval, bounded
 # above/left by the black2 body and below/left by two different yellow bodies.
 identity=dict(authority='R343 independent native visible-body inspection authorized by maker R343 request',native_crop='photo2/r342/review/q1-R332-Y-0104-0097-native.png',source_xy=p.tolist(),separate_body=True,glass_core=REGIONS[C62],not_the_bodies=['MAT25-K-0953-2555','E5-0962-2596','E5-0942-2582'],reason='One exposed amber oval at fixed cue, not a shoulder continuous with the black body above-left or either separated yellow body below-left. Native boundaries and a fixed positive color-material witness precede lattice admission.',maker_confirmed_separate_identity=False,maker_material_pigment='yellow',pattern_color_used=False)
 assert can_admit_identity({},dict(authority='maker material pigment only',separate_body=False)) is False
 occupied={quotient(v,g['H']):o for o,v in co.items()};assert quotient(cell,g['H']) not in occupied;nearest=min(np.linalg.norm(np.array(obs[o]['xy'])-p) for o in co);assert nearest>20
 blocking=[]
 for e in g['edges']:
  a=np.array(obs[e['source']]['xy']);v=np.array(obs[e['target']]['xy'])-a;t=float((p-a)@v/(v@v))
  if .2<t<.8 and np.linalg.norm(p-a-t*v)<7:blocking.append([e['source'],e['target']])
 assert not blocking
 filled,raw=foreground(rgb);blockers={o:r for o,r in obs.items() if o in co or r.get('r336_roles',{}).get('link_obstruction')};blockers[C62]=dict(id=C62,xy=p.tolist(),color='yellow');links=[];audits=[];oldpairs={frozenset([e['source'],e['target']]) for e in g['edges']}
 for e in candidate['neighbors']:
  o=e['target'];delta=e['delta_ab'];family='F0' if delta[1]==0 else 'F1' if delta[0]==0 else 'difference';ck=corridor(C62,o,blockers,filled);rawck=corridor(C62,o,blockers,raw);length=float(np.linalg.norm(np.array(obs[o]['xy'])-p));near=[ed for ed in g['edges'] if ed['family']==family and np.linalg.norm((np.array(obs[ed['source']]['xy'])+obs[ed['target']]['xy'])/2-p)<110];lengths=[np.linalg.norm(np.array(obs[ed['source']]['xy'])-obs[ed['target']]['xy']) for ed in near];ratio=float(length/np.median(lengths));assert ck['allowed'] and .65<=ratio<=1.45;assert quotient(np.array(co[o])-cell-delta,g['H'])==(0,0)
  edge=dict(source=C62,target=o,delta_ab=delta,family=family,origin='R343',status='working link after independent native body and maker pigment checks',foreground_fraction=ck['foreground_fraction'],intervening_observations=[],admission='Separate exposed native body, preserved support, unique local cell/empty occupancy, native corridors, two old triangles; no motif color');links.append(edge);audits.append(dict(edge=edge,filled_corridor=ck,raw_corridor_fraction=rawck['foreground_fraction'],native_length=length,local_family_median=float(np.median(lengths)),length_ratio=ratio,reference_links=[[z['source'],z['target']] for z in near]))
 triangles=[[a['target'],b['target']] for i,a in enumerate(links) for b in links[i+1:] if frozenset([a['target'],b['target']]) in oldpairs];assert len(triangles)>=2 and len({e['family'] for e in links})==3
 baseline=read(ROOT/'photo2/r332/results/omissions.json.gz');oldcandidate=next(r for r in baseline['provisional_native_candidates'] if r['id']==C62);aliases=oldcandidate['alternatives'];assert set(aliases)=={C62,'REC266-P123596'};assert all(o not in obs for o in aliases)
 cache_path=ROOT/'photo2/review/r266/straight-0-selected12/regions.json.gz';cached=next(v for v in read(cache_path)['regions'] if v['id']=='P123596');cache_xy=cached['bright_patch']['patch_centroid'];cx,cy=np.rint(cache_xy).astype(int);mask=Image.new('1',(rgb.shape[1],rgb.shape[0]),0);ImageDraw.Draw(mask).polygon(REGIONS[C62],fill=1);assert mask.getpixel((int(cx),int(cy)))
 alias_evidence=dict(id='REC266-P123596',original_patch_centroid=cache_xy,distance_to_fixed_C62_support=float(np.linalg.norm(np.array(cache_xy)-p)),source=str(cache_path.relative_to(ROOT)),source_sha256=sha(cache_path),source_pixel_runs=cached['pixel_runs'],native_source_inside_independently_inspected_glass=True,identity_basis='Both fixed native cues lie on the one inspected amber body; same lattice group alone was not used as alias proof. Cached boundary pixels are not automatically certified glass.')
 save(OUT/'association.json',dict(id=C62,admitted=True,material_authority='Explicit R343 maker yellow; not a maker identity assertion',independent_native_identity=identity,legacy_maker_only_identity_gate_would_not_admit=True,authorization='R343 explicitly asks whether this provisional body can be admitted after independent visible-body and neighboring-lattice checks. No historical helper or phantom decision is modified.',cell=cell.tolist(),source_xy=p.tolist(),native_prediction=B[2].tolist(),geometric_error=error,site_margin=margin,local_anchors=local,native_affine_coefficients=B.tolist(),colored_anchors=colored,colored_prediction=bc[2].tolist(),prediction_spread=prediction_spread,nearest_existing_distance=float(nearest),occupied_before=False,blocked_old_links=blocking,old_neighbor_triangles=triangles,links=links,link_audit=audits,same_body_cache_aliases=aliases,cache_alias_native_evidence=alias_evidence,old_candidate_provenance={k:oldcandidate[k] for k in ['id','xy','initial_prediction','initial_cell','source','source_kind','source_id']},recentered=False,pigment_or_pattern_used_to_choose_lattice_site=False,historical_duplicate_vetoes_preserved=True))
 print('C62 admitted',error,margin,prediction_spread,[(a['edge']['target'],a['length_ratio'],a['raw_corridor_fraction']) for a in audits])
if __name__=='__main__':main()
